        if (Helpers.isTrue(Helpers.isEqual(version, "status")))
        {
            fullPath = "/status";
            urlPath = "status";
        }
        Object url = Helpers.add(Helpers.GetValue(Helpers.GetValue(this.urls, "api"), urlPath), fullPath);
        parameters = this.omit(parameters, this.extractParams(path));
